import sys

def can_solve_problems(n, k):
    if n < k:
        return False
    min_sum = k * (k + 1) // 2
    max_sum = k * (2 ** k - 1) // (2 ** k - 2)
    if n < min_sum or n > max_sum:
        return False
    return True

def find_training_plan(n, k):
    if not can_solve_problems(n, k):
        return "NO"

    problems_per_day = [0] * k
    remaining_problems = n

    for i in range(k):
        problems_per_day[i] = 1 << i
        remaining_problems -= problems_per_day[i]

    index = 0
    while remaining_problems > 0:
        problems_per_day[index] += 1
        remaining_problems -= 1
        index = (index + 1) % k

    return "YES\n" + " ".join(map(str, problems_per_day))

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    result = find_training_plan(n, k)
    print(result)

if __name__ == "__main__":
    main()
